#[test]
fn rust_mirror_reproduces_the_php_version_four_program() {
    // The pinned version-4 program (the nested-tree grammar) generated
    // by the PHP core: the Rust mirror must reproduce the identical
    // blob and the executed-trace digest.
    let program = execution::generate(KEY, NONCE, "login", "login-action", 4).unwrap();
    assert_eq!(
        program,
        php_vectors::PROGRAM_V4,
        "the Rust generator must reproduce the PHP version-4 program byte-for-byte"
    );
    let decoded = execution::decode(&program).expect("the version-4 program must parse");
    let trace = execution::fixtures::executed_trace_for(&decoded);
    assert!(
        trace.contains("ddepth("),
        "the version-4 grammar carries the nested-tree depth entry"
    );
    assert_eq!(
        execution::expected_digest_over_trace(&program, NONCE, &trace).unwrap(),
        php_vectors::DIGEST_V4,
        "the Rust version-4 executed-trace digest must reproduce the PHP digest"
    );
}

#[test]
fn rust_mirror_reproduces_the_php_version_five_program() {
    // The pinned version-5 program (the causal object-graph grammar)
    // generated by the PHP core: the Rust mirror must reproduce the
    // identical blob, the byte-identical browser-equivalent executed
    // trace and the executed-trace digest.
    let program = execution::generate(KEY, NONCE, "login", "login-action", 5).unwrap();
    assert_eq!(
        program,
        php_vectors::PROGRAM_V5,
        "the Rust generator must reproduce the PHP version-5 program byte-for-byte"
    );
    let decoded = execution::decode(&program).expect("the version-5 program must parse");
    assert_eq!(decoded.op_version, 5);
    let trace = execution::fixtures::executed_trace_for(&decoded);
    assert_eq!(
        trace,
        php_vectors::TRACE_V5,
        "the Rust executed trace must reproduce the PHP fixture trace byte-for-byte"
    );
    assert!(
        trace.contains("dclone(1);drepar(2);u8r(2);durlc("),
        "the version-5 trace carries the clone-reparent spine and the observed URL-canon digest"
    );
    assert_eq!(
        execution::expected_digest_over_trace(&program, NONCE, &trace).unwrap(),
        php_vectors::DIGEST_V5,
        "the Rust version-5 executed-trace digest must reproduce the PHP digest"
    );
    // The URL-canon walker rule: the entry must be 64 lowercase hex
    // digits. An uppercase digest and a short digest are both rejected.
    let upper = trace.replacen("e76cac2d", "E76CAC2D", 1);
    assert!(
        execution::verify_executed_trace(&program, NONCE, &upper).is_none(),
        "an uppercase urlc digest must be rejected"
    );
    let short = trace.replacen(
        "durlc(e76cac2dfcc313d58bb0f731c433badf0651978a1769007ff3c1ab62cf59fee7)",
        "durlc(abc)",
        1,
    );
    assert!(
        execution::verify_executed_trace(&program, NONCE, &short).is_none(),
        "a short urlc digest must be rejected"
    );
}

