#[test]
fn rust_mirror_reproduces_php_generated_program() {
    // The version-2 pair: the Rust generator (version 2, the causal
    // observe grammar) must reproduce the PHP program byte-for-byte,
    // and the executed-trace digest over the executed trace of the
    // program must reproduce the PHP digest (the V2 evidence path).
    let program = execution::generate(KEY, NONCE, "login", "login-action", 2).unwrap();
    assert_eq!(
        program,
        php_vectors::PROGRAM,
        "the Rust generator must reproduce the PHP program byte-for-byte"
    );
    let decoded = execution::decode(&program).expect("the pinned program must parse");
    assert_eq!(decoded.op_version, 2);
    let trace = execution::fixtures::executed_trace_for(&decoded);
    assert_eq!(
        execution::expected_digest_over_trace(&program, NONCE, &trace).unwrap(),
        php_vectors::DIGEST,
        "the Rust executed-trace digest must reproduce the PHP digest"
    );
}

#[test]
fn rust_mirror_reproduces_the_php_version_one_vector() {
    // The version-1 pair (the N-1 grammar): the Rust generator with
    // version 1 must byte-reproduce the PHP version-1 program
    // constant, and the executed-trace digest over its executed trace
    // must reproduce the version-1 digest — so a PHP-issued version-1
    // challenge verifies byte-identically in Rust (and vice versa).
    let program = execution::generate(KEY, NONCE, "login", "login-action", 1).unwrap();
    assert_eq!(
        program,
        php_vectors::PROGRAM_V1,
        "the Rust version-1 generator must reproduce the PHP program byte-for-byte"
    );
    let decoded = execution::decode(&program).expect("the pinned program must parse");
    assert_eq!(decoded.op_version, 1);
    assert!(
        decoded.ops.iter().all(|op| op.opcode != 33),
        "a version-1 program never carries the observe opcode"
    );
    let trace = execution::fixtures::executed_trace_for(&decoded);
    assert!(
        !trace.contains("obs("),
        "a version-1 executed trace never carries the observe entry"
    );
    assert_eq!(
        execution::expected_digest_over_trace(&program, NONCE, &trace).unwrap(),
        php_vectors::DIGEST_V1,
        "the Rust version-1 executed-trace digest must reproduce the PHP digest"
    );
}

#[test]
fn generation_refuses_a_noncanonical_version_byte() {
    // The version argument during generation is a canonical numeric
    // byte, 1..=MAX_EXECUTION_VERSION: any other byte is refused before
    // any program is minted (the strict parser would reject the blob
    // anyway, so issuance never produces an unparseable program).
    assert_eq!(
        execution::generate(KEY, NONCE, "signup", "other-action", 9),
        Err(execution::GenerateError::InvalidVersion)
    );
    assert_eq!(
        execution::generate(KEY, NONCE, "signup", "other-action", 0),
        Err(execution::GenerateError::InvalidVersion)
    );
    // The canonical bytes generate and stamp their own grammar: the
    // first two rungs are sampled here (1 and 2); the higher rungs are
    // covered by the version-ladder suites.
    for version in [1u8, 2u8] {
        let p = execution::generate(KEY, NONCE, "signup", "other-action", version).unwrap();
        assert_eq!(
            execution::decode(&p).expect("must parse").op_version,
            version
        );
    }
}

#[test]
fn version_bytes_cannot_cross_the_grammar_fence() {
    // The N-1 decode fence on the pinned vectors: the version-2
    // program (which carries the observe opcode 33) with its version
    // byte rewritten to 1 must decode to null, and the version-1
    // program with a crafted opcode-33 op must decode to null too.
    let scope_len = b"login".len();
    let action_len = b"login-action".len();
    let version_at = 3 + scope_len + action_len;
    let op0_at = version_at + 2;

    let mut downgraded = B64
        .decode(php_vectors::PROGRAM)
        .expect("the pinned v2 program must decode as base64");
    assert_eq!(downgraded[version_at], 2);
    assert!(execution::decode(php_vectors::PROGRAM).is_some());
    downgraded[version_at] = 1;
    assert!(
        execution::decode(&B64.encode(downgraded)).is_none(),
        "a version-2 program with opcode 33 must never decode as version 1"
    );

    let mut crafted = B64
        .decode(php_vectors::PROGRAM_V1)
        .expect("the pinned v1 program must decode as base64");
    assert_eq!(crafted[version_at], 1);
    assert_eq!(crafted[op0_at], 16, "op 0 is the construction create");
    crafted[op0_at] = 33;
    assert!(
        execution::decode(&B64.encode(crafted)).is_none(),
        "opcode 33 inside a version-1 blob must be rejected"
    );

    // The version-5 grammar is fenced below the version-4 row: the
    // pinned version-5 program (its spine carries opcode 38) rewritten
    // to version 4 must decode to null.
    let mut v5_down = B64
        .decode(php_vectors::PROGRAM_V5)
        .expect("the pinned v5 program must decode as base64");
    assert_eq!(v5_down[version_at], 5);
    v5_down[version_at] = 4;
    assert!(
        execution::decode(&B64.encode(v5_down)).is_none(),
        "a version-5 program with opcode 38 must never decode as version 4"
    );
}

#[test]
fn rust_decodes_and_traces_php_programs() {
    let program = execution::decode(php_vectors::PROGRAM).expect("the PHP program must parse");
    assert_eq!(program.scope, "login");
    assert_eq!(program.action, "login-action");
    assert_eq!(program.op_version, 2);
    assert!(!execution::canonical_trace(&program).is_empty());

    let program_v1 =
        execution::decode(php_vectors::PROGRAM_V1).expect("the PHP version-1 program must parse");
    assert_eq!(program_v1.scope, "login");
    assert_eq!(program_v1.action, "login-action");
    assert_eq!(program_v1.op_version, 1);
    assert!(!execution::canonical_trace(&program_v1).is_empty());
    assert!(!execution::canonical_trace(&program_v1).contains("obs("));
}

